def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(comp)
    template_component = max(components, key=len)
    r0 = min(r for r, c in template_component)
    r1 = max(r for r, c in template_component)
    c0 = min(c for r, c in template_component)
    c1 = max(c for r, c in template_component)
    template = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    th, tw = len(template), len(template[0])
    out = [row[:] for row in grid]
    for comp in components:
        if comp is template_component or len(comp) != 1:
            continue
        mr, mc = comp[0]
        top, left = mr - th // 2, mc - tw // 2
        for dr in range(th):
            for dc in range(tw):
                rr, cc = top + dr, left + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = template[dr][dc]
    return out


